"""Estimate visible lever surface inclination from calibrated RGB-D only."""
import numpy as np,json
from pathlib import Path

def estimate(folder, yrange, zrange):
    p=Path('/app/output')/folder;c='robot0_eye_in_hand';m=json.loads((p/'meta.json').read_text());d=np.load(p/('depth_'+c+'.npy'))[-1].astype(float)
    K=np.array(m['cameras'][c]['intrinsic_cv']);T=np.array(m['cameras'][c]['cam2world_gl']);v,u=np.indices(d.shape)
    P=np.stack([(u-K[0,2])*d/K[0,0],-(v-K[1,2])*d/K[1,1],-d,np.ones_like(d)],-1)@T.T
    q=P[(P[:,:,0]>3.22)&(P[:,:,0]<3.25)&(P[:,:,1]>yrange[0])&(P[:,:,1]<yrange[1])&(P[:,:,2]>zrange[0])&(P[:,:,2]<zrange[1]),:3]
    rng=np.random.default_rng(0);best=None
    for _ in range(1000):
        a,b=q[rng.choice(len(q),2,replace=False)]; dy=b[1]-a[1]
        if abs(dy)<.015:continue
        slope=(b[2]-a[2])/dy;intercept=a[2]-slope*a[1]
        mask=abs(q[:,2]-slope*q[:,1]-intercept)/np.sqrt(1+slope*slope)<.0009
        if best is None or mask.sum()>best[0]:best=(mask.sum(),mask)
    subset=q[best[1]];slope,intercept=np.polyfit(subset[:,1],subset[:,2],1)
    return {'inclination_rad':float(np.arctan(slope)), 'inclination_deg':float(np.degrees(np.arctan(slope))), 'inliers':int(best[0]),'points':len(q)}
if __name__=='__main__':
    initial=estimate('approach1',[-2.535,-2.425],[1.04,1.125]);final=estimate('settled',[-2.53,-2.489],[1.06,1.162]);result={'initial':initial,'final':final,'visible_change_rad':final['inclination_rad']-initial['inclination_rad'],'source':'Calibrated camera depth; geometric estimate, not simulator joint state.'}
    Path('/app/output/visual_verification.json').write_text(json.dumps(result,indent=2));print(json.dumps(result,indent=2))
